	// just read, and it is the part that decides whether the edit is the right SHAPE.
	if len(tests) > 0 {
		fmt.Fprintf(out, "%s\n", searchTextTestHeader)
		for _, result := range tests {
			writeTextSearchResult(out, result, true)
		}
